module traffic_light(
    input rst_n, 
    input clk, 
    input pass_request, 
    output red, 
    output yellow, 
    output green, 
    output [7:0] clock
);
// TODO: Please add your solution here

    localparam idle = 2'b00;
	localparam s1_red = 2'b01;
	localparam s2_yellow = 2'b10;
	localparam s3_green = 2'b11;

	reg [1:0] state, next_state;
    reg [7:0] cnt, next_cnt;
    reg p_red, p_yellow, p_green;
    assign red = p_red;
	assign yellow = p_yellow;
	assign green = p_green;
    always@(posedge clk or negedge rst_n) begin
        if(~rst_n) begin
			state <= idle;
		end
		else begin
			state <= next_state;
		end
	end

	always@(*) begin
	    case(state)
		    idle: begin
		        next_state = s1_red;
		    end
		    s1_red: begin
		        if(cnt==8'd3) begin
		            next_state = s3_green;
		        end
		        else begin
		            next_state = s1_red;
		        end
		    end
		    s2_yellow: begin
		        if(cnt==8'd3) begin
		            next_state = s1_red;
		        end
		        else begin
		            next_state = s2_yellow;
		        end
		    end
		    s3_green: begin
		        if(cnt==8'd3) begin
		            next_state = s2_yellow;
		        end
		        else begin
		            next_state = s3_green;
		        end
		    end
		    default: begin
		    	next_state = idle;
		    end
		endcase
	end


	always@(posedge clk or negedge rst_n) begin
	    if(~rst_n) begin
	        cnt <= 8'd10;
	    end
	    else begin
	    	if(pass_request&&green&&(cnt>8'd10)) begin
	    		cnt <= 8'd10;
	    	end
	    	else if(!green&p_green) begin
	    		cnt <= 8'd60;
	    	end
	    	else if(!yellow&p_yellow) begin
	    		cnt <= 8'd5;
	    	end
	    	else if(!red&p_red) begin
	    		cnt <= 8'd10;
	    	end
	    	else begin
	    		cnt <= cnt-1;
	    	end
	    end
	end



	always@(posedge clk or negedge rst_n) begin
	    if(~rst_n) begin
	        p_red <= 1'b0;
	        p_yellow <= 1'b0;
	        p_green <= 1'b0;
	    end
	    else begin
	    	p_red <= (state==s1_red);
	    	p_yellow <= (state==s2_yellow);
	    	p_green <= (state==s3_green);
	    end
	end


    assign clock = cnt;

endmodule
